  ($c$fruit_cocktail$c$, $c${"minutes": 5, "layers": [{"tone": "strawberry", "ml": 120, "ar": "فراولة", "en": "Strawberry"}, {"tone": "mango", "ml": 120, "ar": "مانجا", "en": "Mango"}, {"tone": "fruit", "ml": 120, "ar": "موز وجوافة", "en": "Banana and guava"}, {"tone": "cream", "ml": 40, "ar": "قشطة وفواكه", "en": "Cream and fruit"}], "steps": [{"icon": "blend", "title_ar": "اضرب كل فاكهة لوحدها", "title_en": "Blend each fruit on its own", "note_ar": "فراولة، مانجا، وموز مع جوافة. كل واحدة مع شوية لبن وسكر.", "note_en": "Strawberry, mango, and banana with guava, each with a little milk and sugar."}, {"icon": "pour", "title_ar": "صبهم طبقات في كوباية طويلة", "title_en": "Pour them in layers in a tall glass", "note_ar": "ببطء على ضهر المعلقة، عشان كل طبقة تفضل لوحدها.", "note_en": "Slowly, over the back of a spoon, so each layer stays apart.", "amount_ar": "حوالي 120 مل كل طبقة", "amount_en": "About 120 ml each"}, {"icon": "top", "title_ar": "حط قشطة وحتت فاكهة على الوش", "title_en": "Top with cream and fruit pieces"}]}$c$),
  ($c$hot_chocolate$c$, $c${"minutes": 4, "layers": [{"tone": "hot_chocolate", "ml": 310, "ar": "لبن بالشوكولاتة", "en": "Chocolate milk"}, {"tone": "cream", "ml": 40, "ar": "كريمة", "en": "Whipped cream"}], "steps": [{"icon": "milk", "title_ar": "سخّن لبن على النار", "title_en": "Heat the milk", "note_ar": "من غير ما يغلي.", "note_en": "Without boiling.", "amount_ar": "300 مل", "amount_en": "300 ml"}, {"icon": "stir", "title_ar": "ضيف كاكاو أو شوكولاتة مبشورة وقلّب", "title_en": "Stir in cocoa or grated chocolate", "note_ar": "وسكر لو الشوكولاتة مش حلوة.", "note_en": "And sugar, if the chocolate isn't sweet.", "amount_ar": "2 معلقة كبيرة", "amount_en": "2 tablespoons"}, {"icon": "top", "title_ar": "صبه وحط كريمة على الوش", "title_en": "Pour it and top with whipped cream", "note_ar": "أو مارشملو.", "note_en": "Or marshmallows."}]}$c$),
