  ($c$cookies_milkshake$c$, $c${"minutes": 3, "layers": [{"tone": "cookies", "ml": 360, "ar": "لبن وآيس كريم وبسكوت مضروبين", "en": "Milk, ice cream and biscuits, blended"}, {"tone": "cream", "ml": 40, "ar": "كريمة وبسكوت", "en": "Cream and biscuit"}], "steps": [{"icon": "blend", "title_ar": "حط في الخلاط لبن وآيس كريم فانيليا", "title_en": "Put milk and vanilla ice cream in the blender", "amount_ar": "200 مل لبن · 2 بولة", "amount_en": "200 ml milk · 2 scoops"}, {"icon": "blend", "title_ar": "ضيف بسكوت بالشوكولاتة واضرب", "title_en": "Add chocolate biscuits and blend", "note_ar": "خلّي فيه حتت صغيرة.", "note_en": "Leave some small pieces.", "amount_ar": "4 بسكوتات", "amount_en": "4 biscuits"}, {"icon": "top", "title_ar": "صبه وحط كريمة وبسكوت مكسّر", "title_en": "Pour it; add whipped cream and crushed biscuit"}]}$c$),
  ($c$berry_smoothie$c$, $c${"minutes": 3, "layers": [{"tone": "berry", "ml": 400, "ar": "توت وموز وزبادي مضروبين", "en": "Berries, banana and yoghurt, blended"}], "steps": [{"icon": "blend", "title_ar": "حط في الخلاط توت فريزر وموزة", "title_en": "Put frozen berries and a banana in the blender", "note_ar": "التوت المتلّج بيخليه ساقع وتقيل من غير تلج.", "note_en": "Frozen berries make it cold and thick without ice.", "amount_ar": "كوباية توت · موزة", "amount_en": "1 cup berries · 1 banana"}, {"icon": "milk", "title_ar": "ضيف زبادي أو لبن وعسل", "title_en": "Add yoghurt or milk and honey", "amount_ar": "150 مل", "amount_en": "150 ml"}, {"icon": "blend", "title_ar": "اضرب لحد ما يبقى ناعم", "title_en": "Blend until smooth"}]}$c$),
